package vn.smarttravel.community.contributions.repository;
import java.util.*;
import org.bson.Document;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.*;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import vn.smarttravel.community.reviews.repository.CommunityRepository;
import vn.smarttravel.community.reviews.client.CatalogClient;

@Repository
public class ContributionRepository {
    private final MongoTemplate mongo;private final CommunityRepository events;private final CatalogClient catalog;
    public ContributionRepository(MongoTemplate mongo,CommunityRepository events,CatalogClient catalog){this.mongo=mongo;this.events=events;this.catalog=catalog;}
    private Query id(String id){UUID.fromString(id);return Query.query(Criteria.where("_id").is(id));}
    public Document get(String id,String user){var row=mongo.findOne(id(id),Document.class,"contributions");if(row==null||!user.equals(row.getString("user_id")))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return row;}
    private Document payload(Map<String,Object> request){Object input=request.getOrDefault("payload",request.get("fields"));if(!(input instanceof Map<?,?> fields)||fields.isEmpty()||fields.size()>20)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payload required");var allowed=Set.of("name","name_vi","name_en","address","description","geographic_unit_id","latitude","longitude","lat","lon","category_ids","tag_ids","amenity_ids","opening_hours","price","price_min","price_max","currency");var result=new Document();for(var entry:fields.entrySet()){String key=entry.getKey().toString();if(!allowed.contains(key))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported contribution field");result.put(key,entry.getValue());}if(result.toJson().length()>16384)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Contribution payload too large");return result;}
    @Transactional public Document create(String user,Map<String,Object> request){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);String type=switch(Objects.toString(request.get("type"),"")){case "ADD","ADD_PLACE"->"ADD_PLACE";case "EDIT","SUGGEST_EDIT"->"SUGGEST_EDIT";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid contribution type");};Date now=new Date();var row=new Document("_id",UUID.randomUUID().toString()).append("user_id",user).append("type",type).append("payload",payload(request)).append("payload_schema_version",1L).append("status","PENDING").append("version",1L).append("created_at",now).append("updated_at",now);
        if(type.equals("SUGGEST_EDIT")){if(request.get("target_id")==null||!(request.get("expected_version") instanceof Number))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Target and expected version required");String target=UUID.fromString(request.get("target_id").toString()).toString();long expected=((Number)request.get("expected_version")).longValue();if(expected<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);catalog.validate(target);row.append("target_id",target).append("expected_version",expected);}else if(request.get("target_id")!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"ADD_PLACE has no target");
        mongo.insert(row,"contributions");audit(row.getString("_id"),user,"CREATED");return row;
    }
    private void audit(String id,String actor,String action){mongo.insert(new Document("_id",UUID.randomUUID().toString()).append("actor",actor).append("aggregate_id",id).append("action",action).append("correlation_id",UUID.randomUUID().toString()).append("occurred_at",new Date()),"audit_logs");}
    private void replace(Document row,long expected){row.put("version",expected+1);row.put("updated_at",new Date());if(mongo.findAndReplace(Query.query(Criteria.where("_id").is(row.getString("_id")).and("version").is(expected)),row,"contributions")==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Contribution version conflict");}
    @Transactional public Document edit(String id,String user,long expected,Map<String,Object> request){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);var row=get(id,user);if(!row.get("status").equals("PENDING")||((Number)row.get("version")).longValue()!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT);row.put("payload",payload(request));replace(row,expected);audit(id,user,"UPDATED");return row;}
    @Transactional public Document withdraw(String id,String user,long expected){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);var row=get(id,user);if(!row.get("status").equals("PENDING")||((Number)row.get("version")).longValue()!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending contributions may withdraw");row.put("status","WITHDRAWN");replace(row,expected);audit(id,user,"WITHDRAWN");return row;}
    public List<Document> list(String user){return mongo.find(Query.query(Criteria.where("user_id").is(user)).limit(100),Document.class,"contributions");}
    public List<Document> pending(){return mongo.find(Query.query(Criteria.where("status").is("PENDING")).limit(100),Document.class,"contributions");}
    @Transactional public Document moderate(String id,String reviewer,long expected,String action,String reason){var row=mongo.findOne(id(id),Document.class,"contributions");if(row==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,row.getString("user_id"));if(!row.get("status").equals("PENDING")||((Number)row.get("version")).longValue()!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT);if(reason==null||reason.isBlank()||!Set.of("APPROVE","REJECT").contains(action))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
        row.put("reason",reason);row.put("approved_by",reviewer);if(action.equals("APPROVE")){String command=UUID.randomUUID().toString();row.put("command_id",command);row.put("status","APPLYING");var commandPayload=new LinkedHashMap<String,Object>();commandPayload.put("command_id",command);commandPayload.put("contribution_id",id);commandPayload.put("approved_by",reviewer);commandPayload.put("type",row.get("type"));commandPayload.put("target_id",row.get("target_id"));commandPayload.put("expected_version",row.get("expected_version"));commandPayload.put("validated_fields",row.get("payload"));events.emit("community.contribution.apply-requested.v1",id,expected+1,commandPayload);}else row.put("status","REJECTED");replace(row,expected);audit(id,reviewer,action);return row;
    }
    @Transactional public boolean result(String event,String command,String contribution,boolean applied,Map<String,Object> payload){
        UUID.fromString(event);var inbox=Query.query(Criteria.where("_id").is("contribution:"+event));if(mongo.exists(inbox,"inbox_events"))return false;
        var row=mongo.findOne(Query.query(Criteria.where("_id").is(contribution).and("command_id").is(command)),Document.class,"contributions");if(row==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Unknown command");
        if(row.get("status").equals("APPLYING")){long version=((Number)row.get("version")).longValue();row.put("status",applied?"APPLIED":"APPLY_FAILED");row.put("apply_result",new Document(payload));replace(row,version);audit(contribution,"catalog",applied?"APPLIED":"APPLY_FAILED");}
        mongo.insert(new Document("_id","contribution:"+event).append("consumer_name","contribution").append("event_id",event).append("processed_at",new Date()).append("producer","catalog"),"inbox_events");return true;
    }
}
